() => {
  // Find the heading with the result count
  const headings = document.querySelectorAll('h2, h3, [data-testid="search-result-count"], .result-count, [class*="count"], [class*="result"]');
  const result = [];
  document.querySelectorAll('*').forEach(el => {
    const text = el.textContent;
    if (text && text.includes('结果') && text.length < 200) {
      result.push({tag: el.tagName, text: text.trim().substring(0, 200), ariaLabel: el.getAttribute('aria-label')});
    }
  });
  // Try to find search result heading directly
  const searchHeading = document.querySelector('[data-testid="search-result-count"]');
  const allH2 = document.querySelectorAll('h2');
  const h2Texts = [];
  allH2.forEach(h => h2Texts.push(h.textContent.trim()));
  return {result_count_elements: result.slice(0, 10), all_h2: h2Texts};
}

() => {
  // Find the heading with the result count
  const results = [];
  // Search in elements with role heading
  document.querySelectorAll('[role="heading"], h1, h2, h3').forEach(el => {
    const text = el.textContent.trim();
    if (text.includes('Machine Learning') || text.includes('结果') || /\d/.test(text)) {
      results.push({tag: el.tagName, text: text.substring(0, 300), html: el.outerHTML.substring(0, 500)});
    }
  });
  return results;
}

() => {
  // Get the search heading and its inner HTML
  const headings = document.querySelectorAll('h2');
  const result = [];
  headings.forEach(h => {
    const txt = h.textContent.trim();
    if (txt.includes('Machine Learning') || txt.includes('结果')) {
      result.push({text: txt, html: h.innerHTML.substring(0, 1000)});
    }
  });
  // Also try to find any element with the count
  const allText = document.body.innerText;
  const match = allText.match(/(\d+,?\d*)\s*个结果/);
  return {headings: result, bodyMatch: match ? match[0] : 'no match', bodyFirst2000: allText.substring(0, 2000)};
}

() => {
  const headings = document.querySelectorAll('h2');
  const result = [];
  headings.forEach((h, idx) => {
    result.push({idx: idx, text: h.textContent, html: h.innerHTML, classes: h.className, ariaLabel: h.getAttribute('aria-label')});
  });
  return result;
}

() => {
  // Search for credit-related terms in the entire page
  const body = document.body.innerText;
  const matches = [];

  // Look for "Credit" or "学分"
  const patterns = [/Credit[^a-zA-Z]/g, /学分/g, /College Credit/gi, /credit eligible/gi];
  patterns.forEach(p => {
    const found = body.match(p);
    if (found) matches.push({pattern: p.source, found: found.slice(0, 10)});
  });

  // Also check all buttons and links
  const buttons = Array.from(document.querySelectorAll('button, a, label, [role="checkbox"]')).map(b => ({
    text: b.textContent.trim().substring(0, 100),
    ariaLabel: b.getAttribute('aria-label')
  })).filter(b => 
    b.text.toLowerCase().includes('credit') || 
    b.text.includes('学分') ||
    b.ariaLabel?.toLowerCase().includes('credit')
  );

  return {matches: matches, buttons: buttons};
}

() => {
  // Look for h2 containing the search results count
  const headings = document.querySelectorAll('h2');
  const out = [];
  headings.forEach((h, i) => {
    out.push({
      idx: i,
      text: h.textContent,
      html: h.outerHTML,
      innerHTML: h.innerHTML
    });
  });
  return out;
}

() => {
  // Find heading with result count
  const headings = document.querySelectorAll('h2, [class*="result"], [data-testid*="result"]');
  const result = [];
  for (const h of headings) {
    if (h.textContent.includes('Machine Learning') || h.textContent.match(/\d+.*结果/)) {
      result.push({
        tag: h.tagName,
        text: h.textContent,
        innerHTML: h.innerHTML.substring(0, 500),
        className: h.className
      });
    }
  }
  return JSON.stringify(result);
}

() => {
  // Find ALL h2 elements and check their text + position
  const headings = Array.from(document.querySelectorAll('h2'));
  const result = headings.map(h => {
    const rect = h.getBoundingClientRect();
    return {
      text: h.textContent.trim(),
      top: Math.round(rect.top),
      left: Math.round(rect.left),
      innerHTML: h.innerHTML
    };
  });
  return JSON.stringify(result, null, 2);
}

() => {
  // Get the heading outer HTML
  const h2 = Array.from(document.querySelectorAll('h2')).find(h => h.textContent.includes('Machine Learning'));
  if (h2) {
    return {
      found: true,
      text: h2.textContent,
      innerHTML: h2.innerHTML,
      outerHTML: h2.outerHTML.substring(0, 2000),
      innerText: h2.innerText,
      children: Array.from(h2.children).map(c => ({tag: c.tagName, text: c.textContent, classes: c.className}))
    };
  }
  return {found: false};
}

() => {
  const result = {};
  // Find h2 with machine learning
  const h2s = document.querySelectorAll('h2');
  for (const h of h2s) {
    if (h.textContent.indexOf('Machine Learning') >= 0) {
      result.h2 = {
        text: h.textContent,
        innerHTML: h.innerHTML,
        outerHTML: h.outerHTML
      };
      break;
    }
  }
  // Also count product cards
  const cards = document.querySelectorAll('[data-testid="product-card-cds"]');
  result.cardCount = cards.length;
  // Also try to find filter and sort button count
  const filterBtn = document.querySelector('[data-testid="filter-and-sort-button"]');
  if (filterBtn) {
    result.filterBtnText = filterBtn.textContent;
  }
  return JSON.stringify(result, null, 2);
}

() => {
  // Look for all elements containing numbers near "结果"
  const all = document.querySelectorAll('*');
  const results = [];
  for (const el of all) {
    const text = el.textContent;
    if (text.includes('Machine Learning') && text.includes('结果') && text.length < 200) {
      results.push({
        tag: el.tagName,
        text: text.substring(0, 200),
        innerHTML: el.innerHTML.substring(0, 500),
        childCount: el.children.length,
        classes: el.className,
        children: Array.from(el.children).map(c => ({tag: c.tagName, text: c.textContent.trim().substring(0, 100)}))
      });
    }
  }
  return results.slice(0, 5);
}

() => {
  // Get the current URL and any related data
  return JSON.stringify({
    url: window.location.href,
    title: document.title,
    productCardCount: document.querySelectorAll('[data-testid="product-card-cds"]').length,
    h2Text: Array.from(document.querySelectorAll('h2')).map(h => h.textContent.trim()),
    filterButton: document.querySelector('[data-testid="filter-and-sort-button"]')?.textContent.trim()
  });
}
